#![allow(clippy::excessive_precision)]
//! Golden-parity tests for cartalith-civ's resource potentials
//! (`buildResourcePotentials`, reference HTML lines 6085-6172).
//! `PHASE2_SCOPE.md` milestone 5. Generated from a Node `vm` extraction
//! run against `reference/Cartalith Gen1 v2.10.html` (harness itself is
//! transient, not checked in) that calls the reference's own
//! `currentLithology()`/`buildBiomeRaster()`/`buildResourcePotentials()`
//! directly, not a hand-composed reimplementation.
//!
//! Cases reuse this crate's existing fixture configs (gw/gh/seed/world/
//! w_iters=12, matching `golden_parity_carrying_capacity.rs` and
//! `cartalith-engine/tests/golden_parity_carve.rs`). Cross-checked before
//! trusting this data: this harness's own `field[0..5]` matched
//! `golden_parity_carve.rs`'s `expected_field[0..5]` exactly for both
//! cases, and determinism was independently confirmed by running each case
//! twice and diffing.
//!
//! Reference default call (`currentResourcePotentials()`, line ~6452)
//! passes no explicit `scarcity`/`scarcityLegacy` -- production runs with
//! `scarcity=true, scarcity_legacy=false`, so these fixtures use those
//! same values (the original six are NOT scarcity-thinned by default; only
//! the nine v1.31 additions are).
//!
//! All 15 outputs are continuous (`Float32Array` in the reference) --
//! `1e-4` absolute+relative tolerance, matching this crate's existing
//! convention.

fn assert_close(actual: &[f32], expected: &[f32], label: &str) {
    const ATOL: f32 = 1e-4;
    const RTOL: f32 = 1e-4;
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (i, (&a, &e)) in actual.iter().zip(expected.iter()).enumerate() {
        let tol = ATOL + RTOL * e.abs();
        assert!(
            (a - e).abs() <= tol,
            "{label} index {i}: got {a}, expected {e} (diff {}, tol {tol})",
            (a - e).abs()
        );
    }
}

